  <style>
    *,
    *::before,
    *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }
    body {
      font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
      background: #f8fafc;
      min-height: 100vh;
      display: flex;
      flex-direction: column;
      align-items: center;
      padding: 40px 20px;
    }
    .page-title {
      font-size: 2rem;
      font-weight: 700;
      color: #1e293b;
      margin-bottom: 8px;
      letter-spacing: -0.5px;
    }
    .page-subtitle {
      font-size: 1.1rem;
      color: #64748b;
      margin-bottom: 48px;
      font-weight: 400;
    }
    .diagram-wrapper {
      background: #ffffff;
      border-radius: 24px;
      padding: 60px;
      box-shadow: 0 10px 40px rgba(0, 0, 0, 0.04), 0 2px 10px rgba(0, 0, 0, 0.02);
      width: 100%;
      max-width: 900px;
      /* Increased to allow more room for flow */
      position: relative;
    }
    svg {
      width: 100%;
      height: auto;
      display: block;
      overflow: visible;
    }
    /* ── Node Styles ── */
    .node-fill {
      fill: #f1f5f9;
    }
    /* Default light blue-gray */
    .node-stroke {
      stroke: #cbd5e1;
    }
    /* Light gray stroke */
    .icon-fill {
      fill: #64748b;
    }
    /* Slate gray for icons */
    /* Special fill for DB and Cloud */
    .db-fill {
      fill: #e0f2fe;
    }
    .ai-fill {
      fill: #e0f2fe;
      stroke-dasharray: 6, 4;
    }
    .flownode rect,
    .flownode ellipse,
    .flownode polygon {
      stroke-width: 1.5;
      transition: stroke 0.2s, filter 0.2s;
    }
    .flownode:hover rect,
    .flownode:hover ellipse,
    .flownode:hover polygon {
      stroke: #0284c7;
      /* Blue hover */
      cursor: pointer;
      filter: drop-shadow(0 2px 6px rgba(2, 132, 199, 0.2));
    }
    /* ── Text Styling ── */
    .label-main {
      font-size: 14px;
      /* increased */
      font-weight: 600;
      fill: #0f172a;
      /* Near black */
      dominant-baseline: middle;
      text-anchor: middle;
    }
    .label-edge {
      font-size: 12px;
      fill: #475569;
      font-weight: 400;
    }
    /* ── Connectors ── */
    .connector {
      fill: none;
      stroke: #94a3b8;
      stroke-width: 2;
    }
    .connector-dashed {
      fill: none;
      stroke: #94a3b8;
      stroke-width: 2;
      stroke-dasharray: 8, 6;
    }
    marker#arrowhead path {
      fill: #94a3b8;
    }
    marker#arrowDashed path {
      fill: #94a3b8;
    }
    /* ── Legend ── */
    .legend {
      margin-top: 40px;
      display: flex;
      flex-wrap: wrap;
      gap: 20px 32px;
      justify-content: center;
      border-top: 1px solid #e2e8f0;
      padding-top: 30px;
    }
    .legend-item {
      display: flex;
      align-items: center;
      gap: 10px;
      font-size: 0.9rem;
      color: #475569;
    }
    /* Legend Shape Icons (using simple divs for brevity) */
    .leg-shape {
      width: 22px;
      height: 16px;
      border-radius: 4px;
      border: 2px solid #cbd5e1;
      background: #f1f5f9;
    }
    .leg-diamond {
      width: 16px;
      height: 16px;
      transform: rotate(45deg);
    }
    .leg-cylinder {
      width: 22px;
      height: 16px;
      border-radius: 50% 50% 4px 4px / 30% 30% 4px 4px;
      border: 2px solid #0284c7;
      background: #e0f2fe;
    }
    .leg-cloud {
      width: 22px;
      height: 16px;
      border-radius: 8px;
      border: 2px dashed #94a3b8;
      background: #e0f2fe;
    }
    .leg-solid {
      width: 30px;
      height: 3px;
      background: #94a3b8;
    }
    .leg-dashed {
      width: 30px;
      height: 3px;
      background: repeating-linear-gradient(90deg, #94a3b8 0, #94a3b8 6px, transparent 6px, transparent 12px);
    }
  </style>
</head>
